                <input type="checkbox" @bind="_pushNotifications" />
                <span>Push Notifications</span>
            </label>

            <label class="toggle-label">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in _channels)
            {
                <label class="toggle-label">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SavePreferences" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Preferences saved successfully!</div>
        }
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _channels = new();

    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _channels = new List<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-bf0f03b6c3f440c095eb7aa6958252aa/Components/Pages/Settings/ChangePasswordPanel.razor", "file_text": "@using sv_bf0f03b6c3f440c095eb7aa6958252aa.Services
@inject ISettingsService SettingsService

<div class="expandable-panel">
    <button class="panel-header" @onclick="() => _expanded = !_expanded">
        <span>Change Password</span>
        <span class="expand-icon">@(_expanded ? "▼" : "▶")</span>
    </button>

    @if (_expanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="toast error">@_error</div>
            }

            @if (_showSuccess)
            {
                <div class="toast success">Password updated successfully!</div>
            }

            <button class="btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                @(_saving ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _error;
    private bool _saving;
    private bool _showSuccess;

    private async Task UpdatePassword()
    {
        _error = null;
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}
"}

{"path": "/tmp/sv-bf0f03b6c3f440c095eb7aa6958252aa/Components/Pages/Settings/ActiveSessionsTable.razor", "file_text": "@using sv_bf0f03b6c3f440c095eb7aa6958252aa.Services
@inject ISettingsService SettingsService

<div class="sessions-section">
    <h3>Active Sessions</h3>

    <table class="sessions-table">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("g")</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn-danger btn-small"
                                    @onclick="() => ConfirmRevoke(session)">
                                Revoke
                            </button>
                        }
                        else
                        {
                            <span class="current-badge">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay">
            <div class="modal-dialog">
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> (@_sessionToRevoke.Location)?</p>
                <div class="button-group">
                    <button class="btn-danger" @onclick="RevokeConfirmed">Revoke Session</button>
                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession> Sessions { get; set; } = new();

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter]
    public EventCallback<string> OnSessionRevoked { get; set; }

    private ActiveSession? _sessionToRevoke;

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeConfirmed()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            await OnSessionRevoked.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }
}
"}

{"path": "/tmp/sv-bf0f03b6c3f440c095eb7aa6958252aa/Components/Pages/Settings/SecuritySection.razor", "file_text": "@using sv_bf0f03b6c3f440c095eb7aa6958252aa.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security</h2>

    @if (_loading)
    {
        <p>Loading security settings...</p>
    }
    else
    {
        <ChangePasswordPanel />

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="status-row">
                <label class="toggle-label">
                    <input type="checkbox" checked="@_twoFactorEnabled" disabled />
                    <span>Two-Factor Authentication</span>
                </label>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("f")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_sessions.FirstOrDefault()?.Id"
                             OnSessionRevoked="HandleSessionRevoked" />
    }
</div>

@code {
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private bool _loading = true;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        _loading = false;
    }

    private void HandleSessionRevoked(string sessionId)
    {
        _sessions.RemoveAll(s => s.Id == sessionId);
    }
}
"}

{"path": "/tmp/sv-bf0f03b6c3f440c095eb7aa6958252aa/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@using sv_bf0f03b6c3f440c095eb7aa6958252aa.Services
@inject ISettingsService SettingsService

<div class="settings-section">
