@using sv_bf0f03b6c3f440c095eb7aa6958252aa.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label><input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange="@(() => _theme = "Light")" /> Light</label>
                <label><input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange="@(() => _theme = "Dark")" /> Dark</label>
                <label><input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange="@(() => _theme = "System")" /> System</label>
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label><input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange="@(() => _fontSize = "Small")" /> Small</label>
                <label><input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange="@(() => _fontSize = "Medium")" /> Medium</label>
                <label><input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange="@(() => _fontSize = "Large")" /> Large</label>
            </div>
        </div>

        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
            </select>
        </div>

        <div class="form-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_compactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <p class="preview-text">This is how your content will look with the selected settings.</p>
            <div class="preview-card">
                <strong>Sample Card</strong>
                <p>Preview of a typical content card with your chosen appearance.</p>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

