@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection"
                    OnSectionSelected="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

arguments.file_text:
namespace sv_bf0f03b6c3f440c095eb7aa6958252aa.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

.settings-dashboard {
    display: flex;
    gap: 2rem;
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
    min-height: 80vh;
}

/* Sidebar */
.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
    min-width: 200px;
}

.settings-sidebar li {
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    border-radius: 6px;
    margin-bottom: 0.25rem;
    transition: background-color 0.2s;
}

.settings-sidebar li:hover {
    background-color: #f0f0f0;
}

.settings-sidebar li.active {
    background-color: #0d6efd;
    color: white;
    font-weight: 600;
}

/* Content area */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
}

.form-group textarea {
    resize: vertical;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    background-color: #0d6efd;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover:not(:disabled) {
    background-color: #0b5ed7;
}

.btn-primary:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-secondary:hover {
    background-color: #5c636a;
}

.btn-danger {
    background-color: #dc3545;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-danger:hover {
    background-color: #bb2d3b;
}

.btn-small {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background-color: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast.error {
    background-color: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #ddd;
}

.avatar-url {
    margin-top: 0.25rem;
    font-size: 0.8rem;
    color: #666;
    word-break: break-all;
}

/* Toggles */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
    padding-left: 0.5rem;
}

/* Expandable panel */
.expandable-panel {
    margin-bottom: 1.5rem;
    border: 1px solid #ddd;
    border-radius: 6px;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #ddd;
}

/* Two-factor */
.two-factor-section {
    margin: 1.5rem 0;
}

.status-row {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.status-indicator {
    padding: 0.25rem 0.5rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 500;
}

.status-indicator.enabled {
    background-color: #d1e7dd;
    color: #0f5132;
}

.status-indicator.disabled {
    background-color: #f8d7da;
    color: #842029;
}

.info-text {
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #eee;
}

.sessions-table th {
    font-weight: 600;
    background: #f8f9fa;
}

.current-badge {
    font-size: 0.8rem;
    color: #0d6efd;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
    font-weight: normal;
}

/* Preview area */
.preview-area {
    margin: 1.5rem 0;
    padding: 1.25rem;
    border: 1px solid #ddd;
    border-radius: 8px;
}

.preview-area.theme-dark {
    background-color: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-light {
    background-color: #ffffff;
    color: #333;
}

.preview-area.theme-system {
    background-color: #f8f9fa;
    color: #333;
}

.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

